// Replicate high-fanout operand
reg [39:0] operand_a, operand_b;
always @(*) {
  operand_a = source;
  operand_b = source;
}
wire prod1 = multiply(operand_a, factor1);
wire prod2 = multiply(operand_b, factor2);

// ATTEMPTED: replication
wire [31:0] b0 = b_q, b1 = b_q;
wire [31:0] prod0 = a * b0, prod1 = a * b1;

// Result: area grows, WNS unchanged, insufficient margin

// INEFFECTIVE: inlined
assign sum = {s0[39], s0} + {s1[39], s1} + {s2[39], s2};

// BETTER: decomposed
wire [39:0] s0_ext = {{8{prod0[31]}}, prod0};
wire [39:0] s1_ext = {{8{prod1[31]}}, prod1};
assign sum = s0_ext + s1_ext + s2_ext;

// Tree: (s0+s1, s2+s3) then their sum
sum_01 = s0 + s1;
sum_23 = s2 + s3;
result = sum_01 + sum_23; // depth 2

// Carry-save attempt:
compressor_3to2(s0, s1, s2, s3, sum, carry);
result = sum + carry; // still high latency from final add

// INEFFECTIVE: carry-save
wire [39:0] ps0 = carry_save_3_2(prod0, prod1, prod2);
wire [39:0] result = carry_save_add(ps0, prod3);

// BETTER: keep ripple
wire [39:0] result = prod0 + prod1 + prod2 + prod3;

// binary state, decoded late
assign en = (state == RUN);
// one-hot, decoded early
always @(posedge clk) en_q <= (next_state == RUN);

// depth 3
assign y = a ? p : b ? q : c ? r : s;
// depth 1 mux tree
always @(*) case (1'b1) a: y=p; b: y=q; c: y=r; default: y=s; endcase

// in the path
always @(posedge clk) q <= rst ? 0 : (a + b);
// on the reset port
always @(posedge clk or negedge rst_n)
  if (!rst_n) q <= 0; else q <= a + b;

// serial
assign y = (s > MAX) ? MAX : (s < MIN) ? MIN : s;
// condition formed from overflow bits available early

// depth 3
wire [W:0] s = ((a + b) + c) + d;
// depth 2, same value
wire [W:0] s = (a + b) + (c + d);

// wide adds
wire [39:0] s = {{8{p0[31]}},p0} + {{8{p1[31]}},p1};
// narrow add, one extension
wire [32:0] t = p0 + p1;

// serial: sum, then compare
wire over = (sum > LIMIT);
// parallel: the top bits already decide it
wire over = |sum[W-1:LIMIT_BITS] & ~sum[W-1];
